class Solution {
    public int countSymmetricIntegers(int low, int high) {
        int ans = 0;
        for (int num = low; num <= high; num++) {
            String s = Integer.toString(num);
            if (s.length() % 2 == 0) {
                int half = s.length() / 2;
                int sum1 = 0, sum2 = 0;
                for (int i = 0; i < half; i++) sum1 += s.charAt(i) - '0';
                for (int i = half; i < s.length(); i++) sum2 += s.charAt(i) - '0';
                if (sum1 == sum2) ans++;
            }
        }
        return ans;
    }
}

