    for (let num = low; num <= high; num++) {
        const s = num.toString();
        if (s.length % 2 === 0) {
            const half = s.length >> 1;
            let sum1 = 0, sum2 = 0;
            for (let i = 0; i < half; i++) sum1 += s.charCodeAt(i) - 48;
            for (let i = half; i < s.length; i++) sum2 += s.charCodeAt(i) - 48;
